SELECT NOTICES_ID, NOTICES_TITLE, NOTICES_IS_PINNED, NOTICES_CREATED_AT, NOTICES_FILE_PATH, NOTICES_CONTENT FROM notices
AND NOTICES_TITLE LIKE CONCAT('%', #{noticeSearchVO.noticeTitle}, '%')
AND NOTICES_CONTENT LIKE CONCAT('%', #{noticeSearchVO.noticeContent}, '%')
AND NOTICES_CREATED_AT >= #{noticeSearchVO.noticeDateStart}
AND NOTICES_CREATED_AT <= #{noticeSearchVO.noticeDateEnd}
ORDER BY NOTICES_ID DESC

SELECT COUNT(*)
FROM notices


        AND NOTICES_TITLE LIKE CONCAT('%', #{noticeSearchVO.noticeTitle}, '%')


        AND NOTICES_CONTENT LIKE CONCAT('%', #{noticeSearchVO.noticeContent}, '%')


        AND NOTICES_CREATED_AT >= #{noticeSearchVO.noticeDateStart}


        AND NOTICES_CREATED_AT <= #{noticeSearchVO.noticeDateEnd}
